@app.get("/home", response_class=HTMLResponse)
def home(request: Request, session: Session = Depends(get_session)):
    user = current_user_from_request(request, session)
    if not user:
        return RedirectResponse(url="/", status_code=303)
    if user.role == "CUSTOMER":
        tickets_list = session.exec(select(Ticket).where(Ticket.user_id == user.id).order_by(Ticket.id.desc())).all()
        tickets_list = filter_tickets(tickets_list, request)
        notifications = get_user_notifications(session, user.id)
        return templates.TemplateResponse(
            "customer.html",
            {
                "request": request,
                "user": user,
                "tickets": tickets_list,
                "ticket_filters": ticket_filter_values(request),
                "high_confidence_threshold": settings.high_confidence_threshold,
                "uncertain_threshold": settings.uncertain_threshold,
                "maximum_ranking_score": maximum_retrieval_ranking_score(),
                "notifications": notifications,
            },
        )
    if user.role in {"IT_SUPPORT", "ADMIN"}:
        return RedirectResponse(url="/support", status_code=303)
    return RedirectResponse(url="/dashboard", status_code=303)

@router.post("/create")
def create_ticket(
    request: Request,
    title: str = Form(...),
    description: str = Form(...),
    session: Session = Depends(get_session),
):
    user = current_user_from_request(request, session)
    if not user:
        return RedirectResponse(url="/", status_code=303)
    if len(title.strip()) < 3 or len(description.strip()) < 10:
        raise HTTPException(status_code=422, detail="Title or description is too short")

    next_number = (session.exec(select(Ticket)).all().__len__()) + 1
    ticket = Ticket(
        ticket_code=f"TCK-{next_number:05d}",
        user_id=user.id,
        title=title.strip(),
        description=description.strip(),
    )
    session.add(ticket)
    try:
        session.commit()
        session.refresh(ticket)
        process_new_ticket(session, ticket)
    except OperationalError as error:
        session.rollback()
        if "database is locked" in str(error).lower():
            raise HTTPException(
                status_code=503,
                detail="The ticket database is temporarily busy. Please wait a moment and submit the ticket again.",
            ) from error
        raise
    return RedirectResponse(url=f"/tickets/{ticket.id}", status_code=303)

